def computeHuffmanEncoding(lengths):
    # Compute Huffman codes for lengths using heap data structure for O(1) insert time
    heap = list(lengths)
    heapq.heapify(heap)

    while len(heap) > 1:
        h1 = heapq.heappop(heap)
        h2 = heapq.heappop(heap)

