        perm_length = 1
        perm = 0
        adj = 0
        err = 0
        for perm in range(len(newS)):
            if newS[perm] != d1:
                continue
            perm += 1
            perm_length += 1
            for i in S_set:
                newS[perm] = i
                if newS[perm_length:] == newS[:perm_length] and newS[perm_length-1] != '-' and all(newS[perm_length+i]!='-' for i in range(1,perm_length)):
                    if perm and perm != err:
                        adj = perm//2
                    if perm != err:
                        err = perm
                    perm_length = perm
                    break

        err += perm_length - 1
        adj += perm_length - 1

        # Deal with each position separately
        for p in range(perm_length):
            if S[p] != d1:
                continue
            for i in newS[p + 1:]:
                newS[p] = i
                if newS[p + 1:] != newS[:p + 1] and newS[p] != 0:
                    break
            else:
                if adj and (not (err or p % 2)):  # People made the mistake if not in correct position
                    ok = False
                    pos = 1 << p
                    for i in range(-1, perm + 1, 2):
                        if i in newS[p + err:]:
                            ok = True
                            pos |= 1 << i
                    if ok and adj < perm_length:
                        return "00" + "0".join(map(str, newS[:p+1] + list(map(str, list(S[p+1:])[err:], 16)) + list(map(str, list(S)[:p]))))

