from heapq import heappop, heappush
from collections import defaultdict

def build_huffman_tree(freq):
    heap = [[f, [i, ""]] for i, f in enumerate(freq)]
    while len(heap) > 1:
        lo = heappop(heap)
        hi = heappop(heap)
        for i in lo[1:]:
            i[1] = f'0{i[1][1]}'
        for i in hi[1:]:
            i[1] = f'1{i[1][1]}'
        heappush(heap, [lo[0] + hi[0]] + lo[1:] + hi[1:])
    return heap[0][1]

def huffman_encoding_message(freq):
    """
    This function takes a frequency mapping of characters and encodes it with Huffman coding.
    """
    huffman_tree = defaultdict(lambda: "000")
    for letter, frequency in freq.items():
        while True:
            huffman_tree = build_huffman_tree(huffman_tree)
            if not huffman_tree or len(huffman_tree[letter]) == 0:
                break
    return huffman_tree

def compute_min_encoding_length(freq, queries):
    """
    This function computes the minimum possible Huffman encoding length for each specified substring.
    """
    encoding_map = huffman_encoding_message(freq)
    min_length = []
    for left, right in queries:
        min_path_len = float("inf")
        current_path = [left-1]
        visited = {left-1}
        while current_path and current_path[0] != right-1:
            current_path.append(None)
            letter, _ = encoding_map[current_path[-1]]
            if letter == letter in encoding_map[current_path[-1]]:
                current_path.pop()
                if current_path:
                    current_path.pop()
                    min_length.append(min(min_length) + (right - left + 1 - len(current_path)) * len(letter) + 1)
            else:
                if (current_path[-1], letter) not in encoding_map:
                    current_path.pop()
                    current_path.pop()
                    if current_path:
                        current_path.pop()
                        min_length.append(min_length[0] - (len(current_path) - 1) * len(letter) + len(letter) + 1)
                else:
                    current_path.pop()
                    if current_path:
                        current_path.pop()
                    min_path_len += 1
        min_length.append(min(min_length))
    return min_length

