def is_tsetso(nums):
    max_value = max(nums)
    for i in range(0, len(nums)):
        if max_value % nums[i] == 0:
            max_value //= nums[i]
            break
    for i in range(len(nums)-1, 0, -1):
        if max_value % nums[i] == 0:
            max_value //= nums[i]
            break
    return max_value == 1

def count_tsetso(nums, queries):
    count = 0
    for L, R in queries:
        L -= 1
        R -= 1
        if L > R:
            continue
        left_valid = 0
        right_valid = 0
        while L >= max(0, R - len(nums) + 1):
            if is_tsetso(nums[L + 1:R]):
                right_valid += 1
            L -= 1
        L -= 1
        while R < len(nums):
            if is_tsetso(nums[L:R+1]):
                left_valid += 1
            R += 1
        count += left_valid * right_valid
    return count

