```python
from functools import reduce
from operator import mul
from math import comb

MOD = 10**9 + 7

def power(a, n):
    res = 1
    base = a
    while n > 0:
        if n & 1:
            res = res * base % MOD
        base = base * base % MOD
        n >>= 1
    return res

def generalized_power(a, n):
    if n == 0:
        return 1
    if n & 1:
        return a * generalized_power(a, n - 1) % MOD
    return generalized_power(a, n // 2) ** 2 % MOD

def binomial(n, k):
    k = min(k, n - k)
    if k == 0:
        return 1
    k = min(k, n - k)
    return reduce(lambda a, b: a * b, [binomial(n, i) for i in range(k + int(k < n - k))])

def exponential(GF):
    a, b = 1, GF(2, 1)
    a, b = a + b, a
    while b > 1:
        if b % 2 == 1:
            a, b = a * b, a
        else:
            b //= 2
        a, b = a, a * b
    return b

def football_roster(n, a):
    FF = GF.Semiring(1, default=0)
    for i in range(n):
        if a[i] % 2 == 1 or a[i] == 0:
            FF[i + 1] = FF(2, a[i])
    return FF

def hockey_roster_FF(GF, n, a):
    for i in range(len(a) - 1, -1, -1):
        if a[i] % 2 == 1 and a[i] != 0:
            # weight the outgoers and initial term
            GF.weight_out(exponential(GF.eval(n, FF.a_pow(i, -a[i]))), GF.a_pow(i, -a[i]))
    return GF

def solve(n, a):
    GF = hockey_roster_FF(GF, n, a)
    ans = GF.eval(n, 1)
    GF.rescale()
    return ans * 2 % MOD

def main(fn):
    with open(fn, 'r') as f:
        n = int(f.readline())
        a = [int(x) for x in f.readline().split()]
    return solve(n, a)

print(main(input().strip()))
