def reconstruct_tree(edges, n):
    edges_count = defaultdict(int)
    for edge in edges:
        u, v = map(int, edge.split())
        edges_count[u] += 1
        edges_count[v] += 1
    root = -1
    while edges_count[root] == 1:
        root = -1
        for u in edges_count:
            if edges_count[u] == n - 2:
                root = u
                break
        if root == -1:
            return "-1"
        edges_count[root] -= 2
    if root == -1:
        return "-1"

    parent = [-1] * n
    required_edges = [(edges_count[root], root)]
    heapq.heapify(required_edges)
    while required_edges:
        edges_count_this, u = heapq.heappop(required_edges)
        if edges_count_this == 1:
            return -1
        if required_edges and required_edges[0] < edges_count[u]:
            heapq.heappush(required_edges, (edges_count[u], u))
        if edges_count_this == 2:
            return u, parent[u] + 1

    if len(required_edges) < n - 2:
        return "-1"

    parent[root] = -1
    for u, required_count in required_edges:
        parent[u] = required_count - 2
        required_edges[:] = [(e - required_edges[-1][0], edge[1] if edge[1] != -1 else u) for e, edge in enumerate(required_edges) if e != len(required_edges) - 1]

    while required_edges:
        n1, onef_count = required_edges[0]
        del required_edges[0]
        n2, one_count = required_edges[0]
        del required_edges[0]
        if len(required_edges) < n1 and len(required_edges) < n2:
            return "-1"
        del required_edges[0]
        n1 -= onef_count + one_count
        parent[n1] = onef_count - 2
        parent[n2] = one_count - 2
    return required_edges

