from heapq import heappush, heappop

def find_largest_traffic(n, m, roads):
    graph = defaultdict(dict)
    for a, b, c in roads:
        graph[a][b] = c
        graph[b][a] = -c  # Roads are two-way, but traffic moves in one direction at a time

    def dijkstra(start, end):
        distances = {node: float('inf') for node in range(1, n+1)}
        distances[start] = 0
        priority_queue = [(0, start)]

        while priority_queue:
            current_distance, current_node = heappop(priority_queue)
            if current_distance > distances[current_node]:
                continue
            for neighbor, weight in graph[current_node].items():
                distance = current_distance + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heappush(priority_queue, (distance, neighbor))

        return distances[end]

    max_traffic = 0
    for j_from in range(1, n):
        for j_to in range(1, n):
            if j_from != j_to:
                max_traffic = max(max_traffic, dijkstra(j_from, j_to))

    print(max_traffic)

    for j_from in range(1, n):
        for j_to in range(1, n):
            if max_traffic / 5.0 > dijkstra(j_from, j_to):
                print(f"{max_traffic / 5:.5f}")
            else:
                print(f"{dijkstra(j_from, j_to):.5f}")

