import collections

def paint_tiles(n, grid):
    graph = collections.defaultdict(list)
    for i in range(n):
        for j in range(n):
            if grid[i][j] != -1:
                for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    if 0 <= i + di < n and 0 <= j + dj < n and grid[i+di][j+dj] == -1:
                        graph[(i, j)].append((i+di, j+dj))

    queue = [(0, ai) for ai in range(1, 1e9)]
    visited = set([(0, ai) for ai in range(1, 1e9)])

    while queue:
        node = queue.pop(0)
        if node in visited:
            continue
        visited.add(node)
        if len(graph[node]) > 0:
            for child in graph[node]:
                if (0, ag) := node; child not in visited:  # ag >= ai
                    queue.append((0, ag))
        queue.append((1, node[1] + 1))  # Start from i = 1

    return node[1]  # node[1] is the minimum cost for painting all non-broken tiles (not necessarily unique)

