import sys

def calculate_expectation(n, strengths):
    mod = 10**9 + 7
    dp = [0] * (n + 1)
    dp[0] = 1
    for win_probability in strengths:
        for j in range(n):
            if j == 0:
                dp[j + 1] = (dp[j] * win_probability) % mod
            elif dp[j] == 0:
                dp[j] = 0
            else:
                dp[j + 1] = (dp[j] * (win_probability / (win_probability + dp[j])) + (1 - dp[j]) * win_probability) % mod
    numerator = 0
    for probability, total_teams in zip(strengths, dp):
        numerator += probability * total_teams
    denominator = 1
    for j in range(n):
        denominator *= strengths[j]
    return (numerator * pow(denominator, mod - 2, mod)) % mod

