import heapq

def find_minimum_contrast(n, grid):
    # Function to compute the minimum contrast for a given row and column
    def compute_contrast(row, col):
        min_val = float('inf')
        max_val = float('-inf')
        for i in range(n):
            for j in range(n):
                if i != row and j != col:
                    min_val = min(min_val, abs(grid[i][j] - grid[row][col]))
                    max_val = max(max_val, abs(grid[i][j] - grid[row][col]))

        return (max_val - min_val) * (n * n - 5)

    # Add boundary tiles to the heap to start the process
    max_heap = []
    for row in range(n):
        for col in range(n):
            if row == 0 or row == n-1 or col == 0 or col == n-1:
                if grid[row][col] != -1:
                    heapq.heappush(max_heap, (-compute_contrast(row, col), grid[row][col], row, col))

    # Extract elements from the heap to compute the final contrast
    while max_heap:
        diff, shade, row, col = heapq.heappop(max_heap)
        diff *= -1
        max_contrast = 0
        for neighbor_row, neighbor_col in [(row-1, col), (row+1, col), (row, col-1), (row, col+1)]:
            if 0 <= neighbor_row < n and 0 <= neighbor_col < n and grid[neighbor_row][neighbor_col] != -1:
                new_diff = compute_contrast((row if neighbor_row == row - 1 else neighbor_row), col if neighbor_row == row - 1 else neighbor_col)
                new_diff *= -1  # Calculate the negative difference to prioritize the smaller ones
                max_contrast += min(new_diff, max_contrast)

        return max_contrast

