import sys
from math import factorial

def calculate_prob_mod_table(n):
    mod_table = [1] * n
    mod_table[0] = 0

    for i in range(1, n):
        mod_table[i] = (mod_table[i-1] * 6) % 1000000007

    return mod_table

def calculate_combinations(n, r):
    return (factorial(n) // (factorial(r) * factorial(n - r)))

def meet_probability(n, m, a, b, p1, p2):
    if a == b:
        return 1.0

    dist = n * (n - 1)
    office_pairs = n * (n - 1) // 2

    mod_table = calculate_prob_mod_table(n)
    if p1 < 0.5:
        p1 = 1 - p1
    if not office_pairs > n:
        fullname = (office_pairs + (m * n)) % 1000000007
    else:
        fullname = p2 * 1000000007 % 1000000007

    c1 = p1 * mod_table[office_pairs] * (mod_table[n] - mod_table[office_pairs]) // (2 * mod_table[fullname])

    if p1 >= 0.5:
        office_pairs = (office_pairs - 2 * p2) // n
    elif not office_pairs > n:
        office_pairs = n + p2 * 2 - fullname

    c2 = p2 * mod_table[office_pairs] * (mod_table[n] - mod_table[office_pairs]) // (2 * mod_table[fullname])
    return (0.5 * (c1 + c2)) % 1000000007

data = tuple(map(int, input().split()))
