from collections import deque, defaultdict

def reconstruct_tree(edges):
    n = len(edges) + 1
    tree = []
    char_to_index = defaultdict(int)
    for i in range(1, n):
        num_chars = len(edges[i - 1])
        char_to_index["".join([('?']*num_chars).join(edges[i - 1])]) = i

    def is_connected(index1, index2, visited):
        queue = deque([(index1, [])])
        while queue:
            current, path = queue.popleft()
            if current == index2:
                return path
            if current in visited:
                continue
            visited.add(current)
            for neighbor in range(1, n):
                if edges[neighbor - 1].count(str(current)) and char_to_index[str(neighbor)] in char_to_index[str(current)]:
                    queue.append((char_to_index[str(neighbor)], path + [current]))
        return []

    for index in range(1, n):
        result = is_connected(index, char_to_index["".join([str(i) for i in edges[-1]])], set())
        if result:
            tree.extend(result)
            break
    return tree

n = int(input().strip())
edges = [input().strip().split() for _ in range(n - 1)]

tree = reconstruct_tree(edges)
if tree:
    print(' '.join(map(str, tree)))
else:
    print('-1')
